/* A - 最大公约数: 欧几里得算法, a,b 可达 1e18, 用 long long */
static long long gcd_ll(long long a, long long b) {
    while (b) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;
    while (T--) {
        long long a, b;
        scanf("%lld %lld", &a, &b);
        printf("%lld\n", gcd_ll(a, b));
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

/*
 * B - 地铁传送最短路
 * k 个可传送站点作为多源起点(距离 0), 求到各目标站点的最短路。
 * 二叉堆 Dijkstra, 支持 0 边权。
 */
#define MAXN 100005
#define MAXE 400005

static int head[MAXN], nxt[MAXE], to[MAXE], ecnt;
static long long wt[MAXE];
static long long dist[MAXN];
static int done[MAXN];

static int hnode[MAXE];
static long long hdist[MAXE];
static int hsz;

static void hpush(int node, long long d) {
    int i = ++hsz;
    hnode[i] = node;
    hdist[i] = d;
    while (i > 1) {
        int p = i >> 1;
        if (hdist[p] <= hdist[i]) break;
        long long td = hdist[p]; hdist[p] = hdist[i]; hdist[i] = td;
        int tn = hnode[p]; hnode[p] = hnode[i]; hnode[i] = tn;
        i = p;
    }
}

static void hpop(int *node, long long *d) {
    *node = hnode[1];
    *d = hdist[1];
    hnode[1] = hnode[hsz];
    hdist[1] = hdist[hsz];
    hsz--;
    int i = 1;
    for (;;) {
        int l = i << 1, r = l | 1, s = i;
        if (l <= hsz && hdist[l] < hdist[s]) s = l;
        if (r <= hsz && hdist[r] < hdist[s]) s = r;
        if (s == i) break;
        long long td = hdist[s]; hdist[s] = hdist[i]; hdist[i] = td;
        int tn = hnode[s]; hnode[s] = hnode[i]; hnode[i] = tn;
        i = s;
    }
}

static void add_edge(int u, int v, long long w) {
    to[ecnt] = v; wt[ecnt] = w; nxt[ecnt] = head[u]; head[u] = ecnt++;
}

static int src[MAXN], tgt[MAXN];

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;
    while (T--) {
        int n, m, k, z;
        scanf("%d %d %d %d", &n, &m, &k, &z);
        ecnt = 0;
        hsz = 0;
        for (int i = 1; i <= n; i++) {
            head[i] = -1;
            dist[i] = -1;
            done[i] = 0;
        }
        for (int i = 0; i < k; i++) scanf("%d", &src[i]);
        for (int i = 0; i < z; i++) scanf("%d", &tgt[i]);
        for (int i = 0; i < m; i++) {
            int u, v;
            long long w;
            scanf("%d %d %lld", &u, &v, &w);
            add_edge(u, v, w);
            add_edge(v, u, w);
        }

        for (int i = 0; i < k; i++) {
            if (src[i] >= 1 && src[i] <= n && dist[src[i]] != 0) {
                dist[src[i]] = 0;
                hpush(src[i], 0);
            }
        }
        while (hsz > 0) {
            int u;
            long long d;
            hpop(&u, &d);
            if (done[u] || d > dist[u]) continue;
            done[u] = 1;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                long long nd = d + wt[e];
                if (dist[v] < 0 || nd < dist[v]) {
                    dist[v] = nd;
                    hpush(v, nd);
                }
            }
        }

        for (int i = 0; i < z; i++) {
            if (i) printf(" ");
            printf("%lld", dist[tgt[i]]);
        }
        printf("\n");
    }
    return 0;
}

