/*
 * C - 单调不降序列
 * 每次操作最多把 k 个位置减 1。
 * 先求"元素级不降的最大目标序列" b: b[n-1]=a[n-1], b[i]=min(a[i], b[i+1])
 * 每个位置需要减 c[i]=a[i]-b[i] 次。
 * 需要的操作数 = max( max(c[i]), ceil(sum(c[i]) / k) )
 */
int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;
    static long long a[200005], b[200005];
    while (T--) {
        int n;
        long long k;
        scanf("%d %lld", &n, &k);
        for (int i = 0; i < n; i++) scanf("%lld", &a[i]);

        b[n - 1] = a[n - 1];
        for (int i = n - 2; i >= 0; i--) b[i] = a[i] < b[i + 1] ? a[i] : b[i + 1];

        long long mx = 0, sum = 0;
        for (int i = 0; i < n; i++) {
            long long c = a[i] - b[i];
            if (c > mx) mx = c;
            sum += c;
        }
        long long need = (sum + k - 1) / k;
        if (need > mx) mx = need;
        printf("%lld\n", mx);
    }
    return 0;
}

