/*
 * D - 静态区间第 k 小 (可持久化权值线段树)
 * 对序列建立 n 个版本的前缀权值线段树, 查询 [l, r] 时用 root[r] - root[l-1] 二分下降。
 */
#define MAXN 200005
#define MAXNODE 4200000

static int lc[MAXNODE], rc[MAXNODE], sumv[MAXNODE];
static int root[MAXN];
static int node_cnt;

static int a[MAXN], vals[MAXN];

static int cmp_int(const void *x, const void *y) {
    int p = *(const int *)x, q = *(const int *)y;
    return (p > q) - (p < q);
}

static int build(int l, int r) {
    int id = ++node_cnt;
    lc[id] = rc[id] = sumv[id] = 0;
    if (l < r) {
        int mid = (l + r) >> 1;
        lc[id] = build(l, mid);
        rc[id] = build(mid + 1, r);
    }
    return id;
}

static int update(int prev, int l, int r, int pos) {
    int id = ++node_cnt;
    lc[id] = lc[prev];
    rc[id] = rc[prev];
    sumv[id] = sumv[prev] + 1;
    if (l < r) {
        int mid = (l + r) >> 1;
        if (pos <= mid) lc[id] = update(lc[prev], l, mid, pos);
        else rc[id] = update(rc[prev], mid + 1, r, pos);
    }
    return id;
}

static int query(int u, int v, int l, int r, int k) {
    if (l == r) return l;
    int mid = (l + r) >> 1;
    int left_cnt = sumv[lc[v]] - sumv[lc[u]];
    if (k <= left_cnt) return query(lc[u], lc[v], l, mid, k);
    return query(rc[u], rc[v], mid + 1, r, k - left_cnt);
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        vals[i] = a[i];
    }

    /* 离散化 */
    qsort(vals + 1, n, sizeof(int), cmp_int);
    int uniq = 0;
    for (int i = 1; i <= n; i++)
        if (i == 1 || vals[i] != vals[uniq]) vals[++uniq] = vals[i];

    root[0] = build(1, uniq);
    for (int i = 1; i <= n; i++) {
        int lo = 1, hi = uniq, pos = 1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            if (vals[mid] == a[i]) { pos = mid; break; }
            if (vals[mid] < a[i]) lo = mid + 1;
            else hi = mid - 1;
        }
        root[i] = update(root[i - 1], 1, uniq, pos);
    }

    while (m--) {
        int l, r, k;
        scanf("%d %d %d", &l, &r, &k);
        printf("%d\n", vals[query(root[l - 1], root[r], 1, uniq, k)]);
    }
    return 0;
}

