/*
 * E - 环形石子合并
 * 断环成链(长度 2n) + 区间 DP: O(n^3)
 */
#define MAXN 205
#define INF 0x3f3f3f3f

static int a[MAXN];
static long long pre[MAXN];
static int fmin[MAXN][MAXN], fmax[MAXN][MAXN];

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    for (int i = n + 1; i <= 2 * n; i++) a[i] = a[i - n];
    for (int i = 1; i <= 2 * n; i++) pre[i] = pre[i - 1] + a[i];

    memset(fmin, 0x3f, sizeof(fmin));
    memset(fmax, 0, sizeof(fmax));
    for (int i = 1; i <= 2 * n; i++) {
        fmin[i][i] = 0;
        fmax[i][i] = 0;
    }

    for (int len = 2; len <= n; len++) {
        for (int i = 1; i + len - 1 <= 2 * n; i++) {
            int j = i + len - 1;
            int best_min = INF, best_max = 0;
            for (int k = i; k < j; k++) {
                int mn = fmin[i][k] + fmin[k + 1][j];
                int mx = fmax[i][k] + fmax[k + 1][j];
                if (mn < best_min) best_min = mn;
                if (mx > best_max) best_max = mx;
            }
            int cost = (int)(pre[j] - pre[i - 1]);
            fmin[i][j] = best_min + cost;
            fmax[i][j] = best_max + cost;
        }
    }

    int ans_min = INF, ans_max = 0;
    for (int i = 1; i <= n; i++) {
        int v1 = fmin[i][i + n - 1];
        int v2 = fmax[i][i + n - 1];
        if (v1 < ans_min) ans_min = v1;
        if (v2 > ans_max) ans_max = v2;
    }
    printf("%d\n%d\n", ans_min, ans_max);
    return 0;
}

