/* G - 逆序对: 归并排序统计, 答案可达 n(n-1)/2, 用 long long */
static long long a[500005], tmp[500005];

static long long msort(int l, int r) { /* 区间 [l, r) */
    if (r - l <= 1) return 0;
    int mid = (l + r) / 2;
    long long cnt = msort(l, mid) + msort(mid, r);
    int i = l, j = mid, k = l;
    while (i < mid && j < r) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            cnt += mid - i;      /* a[i..mid-1] 都大于 a[j] */
            tmp[k++] = a[j++];
        }
    }
    while (i < mid) tmp[k++] = a[i++];
    while (j < r) tmp[k++] = a[j++];
    for (int t = l; t < r; t++) a[t] = tmp[t];
    return cnt;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    printf("%lld\n", msort(0, n));
    return 0;
}

