/*
 * H - 食物链 (带权并查集)
 * rel[x] 表示 x 与父节点的关系: 0 同类, 1 x 吃父, 2 父吃 x (模 3 循环)
 * 同集合内 d(x,y) = (rel[x] - rel[y] + 3) % 3: 0 同类, 1 x 吃 y, 2 y 吃 x
 */
static int fa[50005], rel[50005];

static int find(int x) {
    if (fa[x] == x) return x;
    int root = find(fa[x]);
    rel[x] = (rel[x] + rel[fa[x]]) % 3;
    fa[x] = root;
    return root;
}

int main(void) {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    for (int i = 1; i <= n; i++) {
        fa[i] = i;
        rel[i] = 0;
    }

    int ans = 0;
    while (k--) {
        int op, x, y;
        scanf("%d %d %d", &op, &x, &y);
        if (x > n || y > n) { ans++; continue; }        /* 编号越界 */
        if (op == 2 && x == y) { ans++; continue; }     /* x 吃 x */

        int rx = find(x), ry = find(y);
        if (rx == ry) {
            int d = (rel[x] - rel[y] + 3) % 3;
            if (op == 1 && d != 0) ans++;
            if (op == 2 && d != 1) ans++;
        } else {
            fa[rx] = ry;
            if (op == 1) rel[rx] = (rel[y] - rel[x] + 3) % 3;
            else rel[rx] = (rel[y] - rel[x] + 1 + 3) % 3;
        }
    }
    printf("%d\n", ans);
    return 0;
}

