/*
 * I - Money Buys Happiness
 * 第 i 个月只能买第 i 件物品, 购买前可用总钱数为 (i-1)*x。
 * dp[h] = 获得 h 点快乐所需的最少花费; 逆序枚举 h 保证每月只用一次。
 */
#define MAXH 100005
#define INF 0x3f3f3f3f3f3f3f3fLL

static long long dp[MAXH];
static long long c[55], h[55];

int main(void) {
    int t;
    if (scanf("%d", &t) != 1) return 0;
    while (t--) {
        int m;
        long long x;
        scanf("%d %lld", &m, &x);
        long long total = 0;
        for (int i = 1; i <= m; i++) {
            scanf("%lld %lld", &c[i], &h[i]);
            total += h[i];
        }

        for (long long j = 0; j <= total; j++) dp[j] = INF;
        dp[0] = 0;

        for (int i = 1; i <= m; i++) {
            long long money = (long long)(i - 1) * x;   /* 该月可支配总额 */
            for (long long j = total - h[i]; j >= 0; j--) {
                if (dp[j] == INF) continue;
                if (dp[j] + c[i] <= money && dp[j] + c[i] < dp[j + h[i]])
                    dp[j + h[i]] = dp[j] + c[i];
            }
        }

        long long ans = 0;
        for (long long j = total; j >= 0; j--) {
            if (dp[j] != INF) { ans = j; break; }
        }
        printf("%lld\n", ans);
    }
    return 0;
}

