/*
 * J - 多边形游戏
 * 在凸多边形中选若干两两不重叠、顶点不重复的三角形, 使乘积之和最大。
 * 环复制成长度 2n 的链, f[i][j] 表示区间 [i..j] 的最大得分(长度 <= n)。
 * 按区间最左顶点 i 的归属分解:
 *   f[i][j] = max( f[i+1][j], max_{l} ( C[i][l] + f[l+1][j] ) )
 *   C[i][l] = max_{k} ( f[i+1][k-1] + a_i*a_k*a_l + f[k+1][l-1] )
 * 整体 O(n^3)。
 */
#define MAX2 810

static long long a[MAX2];
static long long f[MAX2][MAX2];
static long long C[MAX2][MAX2];

int main(void) {
    int t;
    if (scanf("%d", &t) != 1) return 0;
    while (t--) {
        int n;
        scanf("%d", &n);
        for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
        for (int i = n + 1; i <= 2 * n + 2; i++) a[i] = a[i - n];
        int N2 = 2 * n;

        for (int i = 0; i <= N2 + 2; i++)
            for (int j = 0; j <= N2 + 2; j++) { f[i][j] = 0; C[i][j] = 0; }

        for (int len = 3; len <= n; len++) {
            for (int i = 1; i + len - 1 <= N2; i++) {
                int j = i + len - 1;

                /* C[i][j] = max_k ( f[i+1][k-1] + a_i a_k a_j + f[k+1][j-1] ) */
                long long cbest = 0;
                for (int k = i + 1; k < j; k++) {
                    long long v = f[i + 1][k - 1] + a[i] * a[k] * a[j] + f[k + 1][j - 1];
                    if (v > cbest) cbest = v;
                }
                C[i][j] = cbest;

                /* f[i][j] = max( f[i+1][j], max_l ( C[i][l] + f[l+1][j] ) ) */
                long long best = f[i + 1][j];
                for (int l = i + 2; l <= j; l++) {
                    long long v = C[i][l] + f[l + 1][j];
                    if (v > best) best = v;
                }
                f[i][j] = best;
            }
        }

        long long ans = 0;
        for (int i = 1; i <= n; i++)
            if (f[i][i + n - 1] > ans) ans = f[i][i + n - 1];
        printf("%lld\n", ans);
    }
    return 0;
}

