/*
 * K - 树上最小 f 值
 * f_i = 顶点 i 到所有被标记顶点的最大距离, 求 min f_i。
 * 结论: 答案 = ceil(D / 2), D 为被标记点集合的直径(树上最远两点距离)。
 * 求直径: 从任一标记点 BFS 到最远标记点 u, 再从 u BFS 得到最大距离即 D。
 */
#define MAXN 200005

static int head[MAXN], nxt[2 * MAXN], to[2 * MAXN], ecnt;
static int ismarked[MAXN], dist[MAXN], que[MAXN];

static void add_edge(int u, int v) {
    to[ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt++;
}

static void bfs(int src, int n) {
    for (int i = 1; i <= n; i++) dist[i] = -1;
    int qh = 0, qt = 0;
    que[qt++] = src;
    dist[src] = 0;
    while (qh < qt) {
        int u = que[qh++];
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (dist[v] < 0) {
                dist[v] = dist[u] + 1;
                que[qt++] = v;
            }
        }
    }
}

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;
    while (T--) {
        int n, k;
        scanf("%d %d", &n, &k);
        ecnt = 0;
        for (int i = 1; i <= n; i++) {
            head[i] = -1;
            ismarked[i] = 0;
        }
        int first = -1;
        for (int i = 0; i < k; i++) {
            int a;
            scanf("%d", &a);
            ismarked[a] = 1;
            if (first < 0) first = a;
        }
        for (int i = 0; i < n - 1; i++) {
            int u, v;
            scanf("%d %d", &u, &v);
            add_edge(u, v);
            add_edge(v, u);
        }

        bfs(first, n);
        int u = first, best = -1;
        for (int i = 1; i <= n; i++)
            if (ismarked[i] && dist[i] > best) { best = dist[i]; u = i; }

        bfs(u, n);
        int D = 0;
        for (int i = 1; i <= n; i++)
            if (ismarked[i] && dist[i] > D) D = dist[i];

        printf("%d\n", (D + 1) / 2);
    }
    return 0;
}

#include <stdio.h>

/*
 * L - 矿区材料 (区间赋值 + 合法性查询)
 * 线段树维护 "区间是否同种材料": same = 0/1/2 统一, -1 混合; lazy 支持区间赋值。
 * 查询 B x y: 区间内必须同种材料; 若 x>1 且 y<N, 还要求 x-1 与 y+1 处材料不同。
 */
#define MAXN 500005

static char s[MAXN + 5];
static int same[4 * MAXN];
static int lazy[4 * MAXN];

static void build(int node, int l, int r) {
    lazy[node] = -1;
    if (l == r) { same[node] = s[l] - 'A'; return; }
    int mid = (l + r) >> 1;
    build(node << 1, l, mid);
    build(node << 1 | 1, mid + 1, r);
    same[node] = (same[node << 1] == same[node << 1 | 1]) ? same[node << 1] : -1;
}

static void apply(int node, int c) { same[node] = c; lazy[node] = c; }

static void push(int node) {
    if (lazy[node] != -1) {
        apply(node << 1, lazy[node]);
        apply(node << 1 | 1, lazy[node]);
        lazy[node] = -1;
    }
}

static void assign_range(int node, int l, int r, int ql, int qr, int c) {
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) { apply(node, c); return; }
    push(node);
    int mid = (l + r) >> 1;
    assign_range(node << 1, l, mid, ql, qr, c);
    assign_range(node << 1 | 1, mid + 1, r, ql, qr, c);
    same[node] = (same[node << 1] == same[node << 1 | 1]) ? same[node << 1] : -1;
}

/* 返回区间统一材料(0/1/2), 混合返回 -1, 无关返回 -2 */
static int query(int node, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return -2;
    if (ql <= l && r <= qr) return same[node];
    push(node);
    int mid = (l + r) >> 1;
    int x = query(node << 1, l, mid, ql, qr);
    int y = query(node << 1 | 1, mid + 1, r, ql, qr);
    if (x == -2) return y;
    if (y == -2) return x;
    if (x == -1 || y == -1 || x != y) return -1;
    return x;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    scanf("%s", s + 1);
    build(1, 1, n);

    int K;
    scanf("%d", &K);
    char op[8];
    while (K--) {
        scanf("%s", op);
        if (op[0] == 'A') {
            int x, y;
            char c[8];
            scanf("%d %d %s", &x, &y, c);
            assign_range(1, 1, n, x, y, c[0] - 'A');
        } else {
            int x, y;
            scanf("%d %d", &x, &y);
            int inside = query(1, 1, n, x, y);
            int ok = (inside != -1);
            if (ok && x > 1 && y < n) {
                int p = query(1, 1, n, x - 1, x - 1);
                int q = query(1, 1, n, y + 1, y + 1);
                if (p == q) ok = 0;
            }
            printf("%s\n", ok ? "Yes" : "No");
        }
    }
    return 0;
}

#include <stdio.h>

/*
 * M - 多重集第 k 小
 * 值域 1..n, 树状数组维护每个值的出现次数:
 *   插入 k (k>0) / 删除第 |k| 小 (k<0)
 * 最后输出任意一个剩余元素(这里输出最大值: 第 total 小)。
 * kth 用树状数组上倍增, O(log n)。
 */
#define MAXN 1000005

static int bit[MAXN];
static int maxv, total;

static void add(int i, int v) {
    for (; i <= maxv; i += i & -i) bit[i] += v;
}

static int kth(int k) { /* 第 k 小(1-based) */
    int pos = 0;
    int step = 1;
    while ((step << 1) <= maxv) step <<= 1;
    for (; step; step >>= 1) {
        if (pos + step <= maxv && bit[pos + step] < k) {
            pos += step;
            k -= bit[pos];
        }
    }
    return pos + 1;
}

int main(void) {
    int n, q;
    if (scanf("%d %d", &n, &q) != 2) return 0;
    maxv = n;
    total = 0;
    for (int i = 0; i < n; i++) {
        int a;
        scanf("%d", &a);
        add(a, 1);
        total++;
    }
    for (int i = 0; i < q; i++) {
        int k;
        scanf("%d", &k);
        if (k > 0) {
            add(k, 1);
            total++;
        } else {
            int v = kth(-k);
            add(v, -1);
            total--;
        }
    }
    if (total == 0) printf("0\n");
    else printf("%d\n", kth(total));
    return 0;
}

#include <stdio.h>

/*
 * N - XOR Array (构造, 答案不唯一)
 * 设前缀异或 P[0..n], 区间 [x,y] 异或为 0 <=> P[x-1] == P[y]。
 * 要求: P[l-1] == P[r], 且其余前缀互不相同。
 * 构造: P[i] = i (i != r), P[r] = l-1; 于是 a_i = P[i] ^ P[i-1]。
 * 所有 a_i 均非 0 且 <= 2^19 左右, 满足 1 <= a_i <= 1e9。
 */
#define MAXN 400005

static long long P[MAXN];

int main(void) {
    int t;
    if (scanf("%d", &t) != 1) return 0;
    while (t--) {
        int n, l, r;
        scanf("%d %d %d", &n, &l, &r);
        for (int i = 0; i <= n; i++) P[i] = i;
        P[r] = l - 1;
        for (int i = 1; i <= n; i++) {
            long long v = P[i] ^ P[i - 1];
            printf("%lld", v);
            if (i < n) printf(" ");
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>

/*
 * O - MAX-MEX Cut
 * 每一列: 混列("01"/"10") 的 MEX = 2; "00" 列单独 MEX = 1; "11" 列单独 MEX = 0。
 * 若相邻两列都是均一列且字符不同, 合并后包含 0 和 1, MEX = 2 (比 1+0 多 1)。
 * 贪心从左到右: 能配对就配对。
 */
static char s1[200005], s2[200005];

int main(void) {
    int t;
    if (scanf("%d", &t) != 1) return 0;
    while (t--) {
        int n;
        scanf("%d", &n);
        scanf("%s", s1);
        scanf("%s", s2);
        long long ans = 0;
        int i = 0;
        while (i < n) {
            if (s1[i] != s2[i]) {
                ans += 2;
                i++;
            } else if (i + 1 < n && s1[i + 1] == s2[i + 1] && s1[i + 1] != s1[i]) {
                ans += 2;
                i += 2;
            } else {
                ans += (s1[i] == '0') ? 1 : 0;
                i++;
            }
        }
        printf("%lld\n", ans);
    }
    return 0;
}
